use std::fmt::Write;
use std::path::Path;

use buck2_e2e::prelude::*;
use serde_json::Value;

// This file was generated by running:
//
// ```
// > buck2 build //:long_build --local-only --no-remote-cache
// > cp $(buck2 log path) buildlog.meta-only.pb.zst
// ```
//
// In the data directory. We check it in instead of re-generating it on every test to get
// deterministic timings
const LOG_SOURCE: &str = "buildlog.meta-only.pb.zst";

#[buck_test]
async fn test_whatup_command(buck: &Buck, tmp_path: &Path) -> anyhow::Result<()> {
    let log = buck.log(&["show", LOG_SOURCE]).await?.stdout;
    let log_file = tmp_path.join("log.json-lines");
    // Truncate log when analysis started
    let mut truncated = String::new();
    for line in log.trim().lines() {
        writeln!(truncated, "{line}")?;
        if line.contains("AnalysisStage") {
            break;
        }
    }
    std::fs::write(&log_file, truncated)?;

    let ext = buck.log(&["whatup", log_file.to_str().unwrap()]).await?;
    golden(&ext.stderr, "at_analysis_start.stderr.golden");
    Ok(())
}

#[buck_test]
async fn test_whatup_after_command(buck: &Buck) -> anyhow::Result<()> {
    // Get event log
    let log = buck.log(&["show", LOG_SOURCE]).await?.stdout;
    let mut elapsed = [0i64, 0i64];

    // Get first timestamp
    let lines: Vec<&str> = log.trim().lines().collect();
    let first_event: Value = serde_json::from_str(lines[1])?;
    let first_timestamp = &first_event["Event"]["timestamp"];
    let timestamp = |t: &Value, i: usize| t[i].as_i64().unwrap();
    // Get timestamp where rule execution starts
    for line in &lines {
        if line.contains("Execute") {
            let event: Value = serde_json::from_str(line)?;
            let event_timestamp = &event["Event"]["timestamp"];
            // Calculate elapsed seconds, we add 1 to give some padding in order to catch the open span
            elapsed[0] = (timestamp(event_timestamp, 0) - timestamp(first_timestamp, 0)) + 1;
            // Calculate elapsed millliseconds
            elapsed[1] =
                (timestamp(event_timestamp, 1) - timestamp(first_timestamp, 1)).div_euclid(1000000);
            break;
        }
    }

    // Verify rule execution appears when running whatup at that timestamp
    let action_start = (elapsed[0] * 1000) + elapsed[1].abs();
    let ext = buck
        .log(&["whatup", LOG_SOURCE, "--after", &action_start.to_string()])
        .await?;
    golden(&ext.stderr, "after_rule_execution.stderr.golden");
    Ok(())
}
